const fs = require("fs");
const path = require("path");

const target = process.argv[2] || path.join(__dirname, "README.md");

let text;
try {
  text = fs.readFileSync(target, "utf8");
} catch (err) {
  console.error(`Unable to read ${target}: ${err.message}`);
  process.exit(1);
}

const count = (text.match(/TODO/g) || []).length;
console.log(count);

